#include <iostream>
#include <string>
using namespace std;

class Cat {
private:
    string name;
    int fish;

public:
    Cat(string n, int f) : name(n), fish(f) {}

    int getFish() const {
        return fish;
    }
};

int main() {
    Cat c1("{name}", {n});
    cout << "本喵的账：" << c1.getFish() << endl;
    return 0;
}
